    <script>
        // Hero Coin Animation
        document.addEventListener('DOMContentLoaded', function() {
            const heroCanvas = document.getElementById('coin-hero');
            const ctx = heroCanvas.getContext('2d');

            let animationTime = 0;
            let isPaused = false;
            let animationFrameId;

            // Set canvas resolution for crisp rendering
            function resizeHero() {
                const container = heroCanvas.parentElement;
                const dpr = window.devicePixelRatio || 1;
                heroCanvas.width = container.clientWidth * dpr;
                heroCanvas.height = container.clientHeight * dpr;

                // Scale context for DPR
                ctx.scale(dpr, dpr);
            }

            resizeHero();
            window.addEventListener('resize', () => {
                resizeHero();
            });

            // Helper function to draw a single coin
            function drawCoin(context, width, height, rotationAngle, tiltAngle) {
                const centerX = width / 2;
                const centerY = height / 2;
                const radius = Math.min(width, height) * 0.4;

                // Save context and apply transformations
                context.save();
                context.translate(centerX, centerY);
                context.rotate(rotationAngle);
                context.rotateX(tiltAngle); // Apply tilt

                // Draw coin with 3D effect
                const thickness = radius * 0.25;

                // Draw reeded edge (visible when not facing directly)
                if (Math.abs(Math.sin(tiltAngle)) > 0.1) {
                    const gradientEdge = context.createRadialGradient(0, 0, radius - thickness/2, 0, 0, radius);
                    gradientEdge.addColorStop(0, '#d4af37');
                    gradientEdge.addColorStop(1, '#b8860b');

                    // Draw edge as a narrow cylinder
                    context.fillStyle = gradientEdge;

                    // Top face
                    context.beginPath();
                    context.arc(0, 0, radius, 0, Math.PI * 2);
                    context.fill();

                    // Side (thick rim)
                    const reedingCount = 60;
                    for(let i=0; i<reedingCount; i++) {
                        const angle1 = (i / reedingCount) * Math.PI * 2;
                        const angle2 = ((i + 1) / reedingCount) * Math.PI * 2;

                        context.beginPath();
                        context.moveTo(Math.cos(angle1) * radius, Math.sin(angle1) * radius);
                        context.lineTo(
                            Math.cos(angle1) * (radius - thickness), 
                            Math.sin(angle1) * (radius - thickness)
                        );
                        context.lineTo(
                            Math.cos(angle2) * (radius - thickness), 
                            Math.sin(angle2) * (radius - thickness)
                        );
                        context.lineTo(Math.cos(angle2) * radius, Math.sin(angle2) * radius);

                        // Alternating light/dark for reeding effect
                        if (i % 2 === 0) {
                            context.fillStyle = '#cda84e';
                        } else {
                            context.fillStyle = '#9a761d';
                        }
                        context.fill();
                    }
                }

                // Draw front face (WastedToken Mint emblem)
                // We use a gradient to simulate metallic reflection
                const frontGradient = context.createRadialGradient(
                    -radius * 0.3, -radius * 0.2, radius * 0.1,
                    0, 0, radius * 1.1
                );
                frontGradient.addColorStop(0, '#ffd700'); // Highlight
                frontGradient.addColorStop(0.2, '#e6c200');
                frontGradient.addColorStop(0.8, '#b8860b');
                frontGradient.addColorStop(1, '#8b6508'); // Shadow

                context.fillStyle = frontGradient;

                // Draw front circle
                context.beginPath();
                context.arc(0, 0, radius, 0, Math.PI * 2);
                context.fill();

                // Add rim detail for front face
                context.lineWidth = thickness * 0.15;
                context.strokeStyle = '#a68423';
                context.stroke();

                // Embossed WastedToken Mint Logo
                context.fillStyle = 'rgba(10, 10, 10, 0.3)'; // Shadow for embossing

                // Text "WASTEDTOKEN"
                context.font = `bold ${radius * 0.25}px 'Courier New', monospace`;
                context.textAlign = 'center';
                context.textBaseline = 'middle';

                // Add embossed text effect with shadow
                const text1Y = -radius * 0.3;
                context.fillText('WASTEDTOKEN', 0, text1Y);

                // Add the raised relief effect by drawing text twice
                context.fillStyle = '#f0e68c'; // Lighter text for relief
                context.fillText('WASTEDTOKEN', 0, text1Y);

                // Text "MINT" below
                context.font = `bold ${radius * 0.2}px 'Courier New', monospace`;
                const text2Y = radius * 0.3;
                context.fillStyle = 'rgba(10, 10, 10, 0.2)';
                context.fillText('MINT', 0, text2Y);

                context.fillStyle = '#d4af37';
                context.fillText('MINT', 0, text2Y);

                // Draw central emblem (a stylized coin symbol)
                const symbolRadius = radius * 0.15;
                context.beginPath();
                context.arc(0, 0, symbolRadius, 0, Math.PI * 2);
                context.fillStyle = '#ffd700';
                context.fill();

                // Inner design for the emblem
                context.strokeStyle = '#b8860b';
                context.lineWidth = radius * 0.03;
                context.beginPath();
                context.arc(0, 0, symbolRadius * 0.5, 0, Math.PI * 2);
                context.stroke();

                // Draw specular highlight (raking effect)
                const highlightX = -Math.sin(rotationAngle) * radius * 0.7;
                const highlightY = -Math.cos(rotationAngle) * radius * 0.3;

                const highlightGradient = context.createRadialGradient(
                    highlightX, highlightY, symbolRadius * 0.2,
                    highlightX, highlightY, radius * 1.2
                );
                highlightGradient.addColorStop(0, 'rgba(255, 255, 255, 0.4)');
                highlightGradient.addColorStop(0.3, 'rgba(255, 255, 255, 0.1)');
                highlightGradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

                context.fillStyle = highlightGradient;
                context.beginPath();
                context.arc(highlightX, highlightY, radius * 1.3, 0, Math.PI * 2);
                context.fill();

                // Draw back face (denomination)
                // We rotate the entire context to draw the other side
                context.save();
                context.rotate(Math.PI); // Flip to背面

                const backGradient = context.createRadialGradient(
                    radius * 0.3, -radius * 0.2, radius * 0.1,
                    0, 0, radius * 1.1
                );
                backGradient.addColorStop(0, '#ffd700');
                backGradient.addColorStop(0.2, '#e6c200');
                backGradient.addColorStop(0.8, '#b8860b');
                backGradient.addColorStop(1, '#8b6508');

                context.fillStyle = backGradient;

                // Draw back circle
                context.beginPath();
                context.arc(0, 0, radius, 0, Math.PI * 2);
                context.fill();

                // Add rim detail for back face
                context.lineWidth = thickness * 0.15;
                context.strokeStyle = '#a68423';
                context.stroke();

                // Denomination text
                context.fillStyle = 'rgba(10, 10, 10, 0.2)'; // Shadow

                const denomTextY = 0; // Center on back face

                // Draw "10,000 TOKENS" with embossed effect
                context.font = `bold ${radius * 0.35}px 'Courier New', monospace`;

                // Shadow text for embossed look
                context.fillStyle = '#2c2c2c';
                context.fillText('10,000', 0, denomTextY - radius * 0.2);

                context.fillStyle = '#d4af37'; // Lighter text
                context.fillText('10,000', 0, denomTextY - radius * 0.2);

                context.font = `bold ${radius * 0.25}px 'Courier New', monospace`;

                context.fillStyle = '#2c2c2c';
                context.fillText('TOKENS', 0, denomTextY + radius * 0.3);

                context.fillStyle = '#d4af37'; // Lighter text
                context.fillText('TOKENS', 0, denomTextY + radius * 0.3);

                // Add back emblem
                const backSymbolRadius = radius * 0.15;
                context.beginPath();
                context.arc(0, 0, backSymbolRadius, 0, Math.PI * 2);
                context.fillStyle = '#ffd700';
                context.fill();

                context.restore(); // Restore rotation for the second face

                context.restore();
            }

            // Animate hero coin
            function animate() {
                if (!isPaused) {
                    animationTime += 0.01;
                    if (animationTime > 1) animationTime = 0;

                    const width = heroCanvas.parentElement.clientWidth;
                    const height = heroCanvas.parentElement.clientHeight;

                    ctx.clearRect(0, 0, width, height);

                    // Calculate rotation and tilt for coin animation
                    // Full rotation (2π) plus some tilt
                    const rotation = animationTime * Math.PI * 2;
                    // Tilt to show both faces: oscillate between -0.5 and 0.5 radians
                    const tilt = Math.sin(animationTime * Math.PI * 2) * 0.6;

                    drawCoin(ctx, width, height, rotation, tilt);
                }

                animationFrameId = requestAnimationFrame(animate);
            }

            // Initialize animation
            animate();

            // Expose API to window.demo
            window.demo = {
                canvas: heroCanvas,

                setTime(t) {
                    // Clamp t between 0 and 1
                    const clampedT = Math.max(0, Math.min(1, t));

                    // Calculate rotation and tilt based on time
                    const width = heroCanvas.parentElement.clientWidth;
                    const height = heroCanvas.parentElement.clientHeight;

                    const rotation = clampedT * Math.PI * 2;
                    const tilt = Math.sin(clampedT * Math.PI * 2) * 0.6;

                    ctx.clearRect(0, 0, width, height);
                    drawCoin(ctx, width, height, rotation, tilt);
                },

                pause() {
                    isPaused = true;
                    if (animationFrameId) {
                        cancelAnimationFrame(animationFrameId);
                    }
                }
            };

            // Function to draw edition coins
            function drawEditionCoin(canvas, type) {
                const ctx = canvas.getContext('2d');
                const width = canvas.offsetWidth || 300;
                const height = canvas.offsetHeight || 250;

                canvas.width = width * 2;
                canvas.height = height * 2;

                ctx.scale(2, 2);

                // Draw the coin centered
                drawCoin(
                    ctx, 
                    width, 
                    height,
                    Math.PI / 4, // Fixed rotation for preview
                    -0.3 // Slight tilt
                );
            }

            // Initialize edition coins
            const editionCanvases = document.querySelectorAll('.edition-canvas');

            for (let i = 0; i < editionCanvases.length; i++) {
                const canvas = editionCanvases[i];
                const parent = canvas.parentElement;
                const editionType = parent.dataset.edition;

                // Set canvas dimensions
                canvas.style.width = '100%';
                canvas.style.height = (parent.offsetWidth / 1.2) + 'px';

                // Draw appropriate coin based on type
                if (editionType === 'bronze') {
                    // Adjust drawCoin to handle color differences if needed
                    drawEditionCoin(canvas, 'bronze');
                } else if (editionType === 'silver') {
                    drawEditionCoin(canvas, 'silver');
                } else if (editionType === 'gold') {
                    drawEditionCoin(canvas, 'gold');
                } else if (editionType === 'black') {
                    // For black obsidian edition, we need to modify the coin drawing slightly
                    const canvasCtx = canvas.getContext('2d');
                    const width = canvas.offsetWidth || 300;
                    const height = canvas.offsetHeight || 250;

                    canvas.width = width * 2;
                    canvas.height = height * 2;

                    canvasCtx.scale(2, 2);
                    drawObsidianCoin(canvasCtx, width, height);
                }
            }

            // Function to draw obsidian black coin
            function drawObsidianCoin(context, width, height) {
                const centerX = width / 2;
                const centerY = height / 2;
                const radius = Math.min(width, height) * 0.4;

                context.save();
                context.translate(centerX, centerY);

                // Draw reeded edge
                if (true) { // Always show edges for obsidian
                    const gradientEdge = context.createRadialGradient(0, 0, radius - 15, 0, 0, radius);
                    gradientEdge.addColorStop(0, '#3a3a3a');
                    gradientEdge.addColorStop(1, '#1a1a1a');

                    context.fillStyle = gradientEdge;

                    const reedingCount = 60;
                    for(let i=0; i<reedingCount; i++) {
                        const angle1 = (i / reedingCount) * Math.PI * 2;
                        const angle2 = ((i + 1) / reedingCount) * Math.PI * 2;

                        context.beginPath();
                        context.moveTo(Math.cos(angle1) * radius, Math.sin(angle1) * radius);
                        context.lineTo(
                            Math.cos(angle1) * (radius - 15), 
                            Math.sin(angle1) * (radius - 15)
                        );
                        context.lineTo(
                            Math.cos(angle2) * (radius - 15), 
                            Math.sin(angle2) * (radius - 15)
                        );
                        context.lineTo(Math.cos(angle2) * radius, Math.sin(angle2) * radius);

                        if (i % 2 === 0) {
                            context.fillStyle = '#3a3a3a';
                        } else {
                            context.fillStyle = '#1a1a1a';
                        }
                        context.fill();
                    }
                }

                // Draw front face with obsidian effect
                const frontGradient = context.createRadialGradient(
                    -radius * 0.2, -radius * 0.2, radius * 0.1,
                    0, 0, radius * 1.1
                );
                frontGradient.addColorStop(0, '#8a8a8a'); // Highlight
                frontGradient.addColorStop(0.3, '#2a2a2a');
                frontGradient.addColorStop(0.7, '#0a0a0a');
                frontGradient.addColorStop(1, '#000000'); // Shadow

                context.fillStyle = frontGradient;

                // Draw front circle
                context.beginPath();
                context.arc(0, 0, radius, 0, Math.PI * 2);
                context.fill();

                // Add rim detail for front face
                context.lineWidth = 15 * 0.15;
                context.strokeStyle = '#333';
                context.stroke();

                // Embossed WastedToken Mint Logo for black coin
                const text1Y = -radius * 0.3;

                // Draw "WASTEDTOKEN" with embossed effect using lighter color on dark background
                context.font = `bold ${radius * 0.25}px 'Courier New', monospace`;
                context.textAlign = 'center';
                context.textBaseline = 'middle';

                // Shadow text for embossed look
                context.fillStyle = '#1a1a1a'; 
                context.fillText('WASTEDTOKEN', 0, text1Y);

                context.fillStyle = '#5c5c5c'; // Lighter text for relief
                context.fillText('WASTEDTOKEN', 0, text1Y);

                // Text "MINT" below
                const text2Y = radius * 0.3;
                context.font = `bold ${radius * 0.2}px 'Courier New', monospace`;

                context.fillStyle = '#1a1a1a';
                context.fillText('MINT', 0, text2Y);

                context.fillStyle = '#5c5c5c'; // Lighter text
                context.fillText('MINT', 0, text2Y);

                // Draw central emblem (a stylized coin symbol)
                const symbolRadius = radius * 0.15;
                context.beginPath();
                context.arc(0, 0, symbolRadius, 0, Math.PI * 2);
                context.fillStyle = '#4a4a4a';
                context.fill();

                // Inner design for the emblem
                context.strokeStyle = '#3a3a3a';
                context.lineWidth = radius * 0.03;
                context.beginPath();
                context.arc(0, 0, symbolRadius * 0.5, 0, Math.PI * 2);
                context.stroke();

                // Draw specular highlight (raking effect)
                const highlightX = -Math.sin(Math.PI / 4) * radius * 0.7;
                const highlightY = -Math.cos(Math.PI / 4) * radius * 0.3;

                const highlightGradient = context.createRadialGradient(
                    highlightX, highlightY, symbolRadius * 0.2,
                    highlightX, highlightY, radius * 1.2
                );
                highlightGradient.addColorStop(0, 'rgba(255, 255, 255, 0.3)');
                highlightGradient.addColorStop(0.3, 'rgba(255, 255, 255, 0.1)');
                highlightGradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

                context.fillStyle = highlightGradient;
                context.beginPath();
                context.arc(highlightX, highlightY, radius * 1.3, 0, Math.PI * 2);
                context.fill();

                // Draw back face
                context.save();
                context.rotate(Math.PI); // Flip to背面

                const backGradient = context.createRadialGradient(
                    radius * 0.2, -radius * 0.2, radius * 0.1,
                    0, 0, radius * 1.1
                );
                backGradient.addColorStop(0, '#8a8a8a');
                backGradient.addColorStop(0.3, '#2a2a2a');
                backGradient.addColorStop(0.7, '#0a0a0a');
                backGradient.addColorStop(1, '#000000');

                context.fillStyle = backGradient;

                // Draw back circle
                context.beginPath();
                context.arc(0, 0, radius, 0, Math.PI * 2);
                context.fill();

                // Add rim detail for back face
                context.lineWidth = 15 * 0.15;
                context.strokeStyle = '#333';
                context.stroke();

                // Denomination text with obsidian effect
                const denomTextY = 0;

                context.font = `bold ${radius * 0.35}px 'Courier New', monospace`;

                // Shadow text for embossed look
                context.fillStyle = '#1a1a1a';
                context.fillText('10,000', 0, denomTextY - radius * 0.2);

                context.fillStyle = '#5c5c5c'; // Lighter text
                context.fillText('10,000', 0, denomTextY - radius * 0.2);

                context.font = `bold ${radius * 0.25}px 'Courier New', monospace`;

                context.fillStyle = '#1a1a1a';
                context.fillText('TOKENS', 0, denomTextY + radius * 0.3);

                context.fillStyle = '#5c5c5c'; // Lighter text
                context.fillText('TOKENS', 0, denomTextY + radius * 0.3);

                // Add back emblem
                const backSymbolRadius = radius * 0.15;
                context.beginPath();
                context.arc(0, 0, backSymbolRadius, 0, Math.PI * 2);
                context.fillStyle = '#4a4a4a';
                context.fill();

                context.restore(); // Restore rotation for the second face

                context.restore();
            }

            // Add hover effects for edition cards
            const editionCards = document.querySelectorAll('.edition');

            editionCards.forEach(card => {
                card.addEventListener('mouseenter', () => {
                    if (card.dataset.state === 'available') {
                        card.style.boxShadow = '0 16px 48px rgba(255, 215, 0, 0.3), 0 0 30px var(--accent-gold)';
                    }
                });

                card.addEventListener('mouseleave', () => {
                    if (card.dataset.state === 'available') {
                        card.style.boxShadow = '';
                    }
                });
